let stream=null,photoUrl=null,capturedAt=null,mode='ยืม',cameraRequest=0;
const dialog=document.querySelector('#cameraDialog'),video=document.querySelector('#video'),photo=document.querySelector('#photo'),capture=document.querySelector('#capture');
const modes=[...document.querySelectorAll('[data-mode]')];
function stopCamera(){cameraRequest++;if(stream)stream.getTracks().forEach(track=>track.stop());stream=null;video.srcObject=null;video.hidden=true;capture.disabled=true;}
function discardPhoto(){if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=null;capturedAt=null;photo.removeAttribute('src');photo.hidden=true;document.querySelector('#evidenceDetails').hidden=true;document.querySelector('#faceConfirm').checked=false;document.querySelector('#review').disabled=true;document.querySelector('#reviewStatus').hidden=true;document.querySelector('#retake').hidden=true;}
function reset(){stopCamera();discardPhoto();document.querySelector('#cameraPlaceholder').hidden=false;document.querySelector('#cameraError').hidden=true;document.querySelector('#openCamera').disabled=false;}
document.querySelector('#tryCamera').addEventListener('click',()=>{reset();dialog.showModal();});
document.querySelector('#closeCamera').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',reset);window.addEventListener('pagehide',reset);
async function openCamera(){
 reset();const request=++cameraRequest;const button=document.querySelector('#openCamera');button.disabled=true;
 try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('UNSUPPORTED');const incoming=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:1280},height:{ideal:720}},audio:false});if(request!==cameraRequest||!dialog.open){incoming.getTracks().forEach(track=>track.stop());return;}stream=incoming;video.srcObject=stream;video.hidden=false;document.querySelector('#cameraPlaceholder').hidden=true;await video.play();capture.disabled=!(video.videoWidth>0);}
 catch(error){if(request!==cameraRequest)return;stopCamera();const message=error.name==='NotAllowedError'?'กรุณาอนุญาตให้เว็บไซต์ใช้กล้อง แล้วลองเปิดกล้องอีกครั้ง':error.name==='NotFoundError'?'ไม่พบกล้องบนอุปกรณ์นี้':error.name==='NotReadableError'?'กล้องอาจถูกใช้งานโดยโปรแกรมอื่น กรุณาปิดโปรแกรมนั้นแล้วลองใหม่':'เปิดกล้องไม่ได้ ลองเปิดเว็บไซต์ในเบราว์เซอร์และตรวจสิทธิ์การใช้กล้อง';const element=document.querySelector('#cameraError');element.textContent=message;element.hidden=false;document.querySelector('#cameraPlaceholder').hidden=false;button.disabled=false;}
}
document.querySelector('#openCamera').addEventListener('click',openCamera);document.querySelector('#retake').addEventListener('click',openCamera);
video.addEventListener('loadeddata',()=>{if(stream)capture.disabled=video.videoWidth===0;});
capture.addEventListener('click',()=>{if(!stream||!video.videoWidth)return;const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);const request=cameraRequest;capturedAt=new Date();const shotTime=capturedAt;capture.disabled=true;canvas.toBlob(blob=>{if(!blob||request!==cameraRequest||!dialog.open)return;photoUrl=URL.createObjectURL(blob);photo.src=photoUrl;photo.hidden=false;stopCamera();document.querySelector('#evidenceDetails').hidden=false;document.querySelector('#retake').hidden=false;document.querySelector('#openCamera').disabled=true;document.querySelector('#photoMode').textContent='ภาพตอน'+mode;const time=document.querySelector('#photoTime');time.dateTime=shotTime.toISOString();time.textContent=shotTime.toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'long',year:'numeric'})+' · '+shotTime.toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})+' น.';},'image/jpeg',.85);});
modes.forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;reset();modes.forEach(b=>{const active=b.dataset.mode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}));
document.querySelector('#faceConfirm').addEventListener('change',event=>{document.querySelector('#review').disabled=!event.target.checked||!photoUrl;document.querySelector('#reviewStatus').hidden=true;});
document.querySelector('#review').addEventListener('click',()=>{if(selectedLoan||!photoUrl||!document.querySelector('#faceConfirm').checked)return;const status=document.querySelector('#reviewStatus');status.textContent='ภาพหลักฐานพร้อมสำหรับตรวจหน้าจอ ยังไม่ได้ยืม คืน หรือบันทึกข้อมูลจริง ระบบยังไม่ได้ตรวจจับใบหน้าอัตโนมัติ';status.hidden=false;});
const tabs=[...document.querySelectorAll('[data-view]')];tabs.forEach(button=>button.addEventListener('click',()=>{const mine=button.dataset.view==='mine';tabs.forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.querySelector('#sectionTitle').textContent=mine?'รายการยืมของฉัน':'อุปกรณ์พร้อมยืม';document.querySelector('#emptyTitle').textContent=mine?'เข้าสู่ระบบเพื่อดูรายการยืมของคุณ':'ยังไม่มีรายการอุปกรณ์';document.querySelector('#emptyText').textContent=mine?'รายการอุปกรณ์และเวลายืม–คืนจะแสดงเมื่อเชื่อมระบบสมาชิกแล้ว':'รายการอุปกรณ์ที่ผู้ดูแลเพิ่มจะแสดงที่นี่';document.querySelector('#loginLink').hidden=!mine;}));
let equipmentData={equipment:[],loans:[]},equipmentView='available',selectedLoan=null;
function startEvidence(record,operation){if(!sessionStorage.getItem('vc-session')){location.href='login.html';return;}const own=equipmentData.loans.filter(l=>l.equipmentId===record.id&&l.memberId===equipmentData.currentUser?.id&&!l.returnedAt).sort((a,b)=>new Date(b.borrowedAt)-new Date(a.borrowedAt));selectedLoan={id:record.id,loanId:operation==='คืน'?own[0]?.id:null};mode=operation;reset();modes.forEach(b=>{const active=b.dataset.mode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));b.disabled=true;});document.querySelector('.dialoghead h2').textContent=mode+'อุปกรณ์ · '+record.name;document.querySelector('.previewnote').textContent='ภาพจะบันทึกลง Drive และแสดงใต้อุปกรณ์นี้';document.querySelector('#review').textContent='ยืนยัน'+mode+'อุปกรณ์ →';dialog.showModal();}
function renderEquipment(){const list=document.querySelector('#equipmentList');list.replaceChildren();equipmentData.equipment.forEach(record=>{const card=document.createElement('article');card.className='equipmentcard';card.id='equipment-'+record.id;const title=document.createElement('h3');title.textContent=record.name;const info=document.createElement('p');info.textContent=record.detail||'';card.append(title,info);if(record.image){const image=document.createElement('img');image.className='equipmentcover';image.src=record.image;image.alt=record.name;card.append(image);}const actions=document.createElement('div');actions.className='equipmentactions';for(const operation of ['ยืม','คืน']){const button=document.createElement('button');button.textContent='ถ่ายภาพ'+operation+'อุปกรณ์';button.addEventListener('click',()=>startEvidence(record,operation));actions.append(button);}card.append(actions);const history=equipmentData.loans.filter(l=>l.equipmentId===record.id).sort((a,b)=>new Date(b.returnedAt||b.borrowedAt)-new Date(a.returnedAt||a.borrowedAt));history.forEach((loan,index)=>{const evidence=document.createElement('div');evidence.className='equipmenthistory';const label=document.createElement('p');label.textContent='หลักฐานของ '+loan.memberName;evidence.append(label);if(index===0)appendLoanPhotos(evidence,loan);else{const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='ดูภาพยืม / คืนรายการนี้';details.append(summary);let loaded=false;details.addEventListener('toggle',()=>{if(details.open&&!loaded){loaded=true;appendLoanPhotos(details,loan);}});evidence.append(details);}card.append(evidence);});list.append(card);});document.querySelector('#equipmentEmpty').hidden=equipmentData.equipment.length>0;document.querySelector('.resultshead span').textContent=equipmentData.equipment.length+' รายการ';document.querySelector('#emptyTitle').textContent='ยังไม่มีรายการอุปกรณ์';document.querySelector('#emptyText').textContent='ผู้ดูแลสามารถเพิ่มอุปกรณ์จาก CMS';}
async function loadEquipment(){try{equipmentData=await VC_API.call('load');renderEquipment();await VC_API.images(equipmentData.equipment,'equipmentImage',()=>renderEquipment());}catch(e){document.querySelector('#emptyTitle').textContent='โหลดอุปกรณ์ไม่สำเร็จ';document.querySelector('#emptyText').textContent=e.message;}}
tabs.forEach(button=>button.addEventListener('click',()=>{equipmentView=button.dataset.view;renderEquipment();}));
document.querySelector('#tryCamera').addEventListener('click',()=>{selectedLoan=null;modes.forEach(b=>b.disabled=false);document.querySelector('.dialoghead h2').textContent='ทดลองถ่ายภาพหลักฐาน';document.querySelector('.previewnote').textContent='ทดลองกล้องเท่านั้น · ยังไม่บันทึกภาพ';document.querySelector('#review').textContent='ตรวจสอบภาพหลักฐาน →';});
document.querySelector('#review').addEventListener('click',async()=>{if(!selectedLoan||!photoUrl||!document.querySelector('#faceConfirm').checked)return;const button=document.querySelector('#review');button.disabled=true;try{const response=await fetch(photoUrl);const image=new File([await response.blob()],'evidence.jpg',{type:'image/jpeg'});await VC_API.call(mode==='ยืม'?'borrow':'return',{id:selectedLoan.id,loanId:selectedLoan.loanId,photo:await VC_API.file(image),faceConfirmed:true,capturedAt:capturedAt.toISOString()});dialog.close();equipmentView='available';document.querySelector('#sectionTitle').textContent='อุปกรณ์ชมรม';await loadEquipment();alert('บันทึกรายการ'+mode+'สำเร็จ');}catch(e){document.querySelector('#reviewStatus').textContent=e.message;document.querySelector('#reviewStatus').hidden=false;button.disabled=false;}});
loadEquipment();
const loanPhotoCache=new Map();
function appendLoanPhotos(card,loan){const group=document.createElement('div');group.className='loanphotos';for(const phase of ['borrow','return']){const figure=document.createElement('figure');figure.className='loanphoto';const caption=document.createElement('figcaption');caption.textContent=phase==='borrow'?'ภาพตอนยืม':'ภาพตอนคืน';const time=document.createElement('time');const timestamp=phase==='borrow'?loan.borrowedAt:loan.returnedAt;time.textContent=timestamp?new Date(timestamp).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}):'ยังไม่มีภาพ';if(timestamp)time.dateTime=timestamp;const content=document.createElement('div');figure.append(caption,time,content);group.append(figure);if(loan[phase==='borrow'?'borrowPhotoDeleted':'returnPhotoDeleted']){const note=document.createElement('p');note.className='photofallback';note.textContent='ผู้ดูแลลบภาพนี้แล้ว';content.append(note);}else if(!timestamp){const note=document.createElement('p');note.className='photofallback';note.textContent=phase==='borrow'?'ยังไม่มีภาพตอนยืม':'ยังไม่มีภาพตอนคืน';content.append(note);}else loadLoanPhoto(content,loan,phase);}card.append(group);}
async function loadLoanPhoto(container,loan,phase){const key=loan.id+':'+phase;container.replaceChildren();const status=document.createElement('p');status.className='photofallback';status.textContent='กำลังโหลดภาพ…';container.append(status);try{let src=loanPhotoCache.get(key);if(!src){const data=await VC_API.call('loanPhoto',{id:loan.id,phase});if(!data?.base64||!['image/jpeg','image/png','image/webp'].includes(data.mime))throw Error('รูปแบบภาพไม่ถูกต้อง');src='data:'+data.mime+';base64,'+data.base64;loanPhotoCache.set(key,src);}container.replaceChildren();const button=document.createElement('button');button.type='button';const image=document.createElement('img');image.src=src;image.alt=(phase==='borrow'?'ภาพตอนยืม':'ภาพตอนคืน')+' '+loan.equipmentName;image.loading='lazy';button.setAttribute('aria-label','ขยาย'+image.alt);button.append(image);button.addEventListener('click',()=>{document.querySelector('#viewerTitle').textContent=image.alt;document.querySelector('#viewerImage').src=src;document.querySelector('#photoViewer').showModal();});container.append(button);if(equipmentData.currentUser?.role==='admin'){const remove=document.createElement('button');remove.type='button';remove.className='deletephoto';remove.textContent='ลบภาพ'+(phase==='borrow'?'ตอนยืม':'ตอนคืน');remove.addEventListener('click',async()=>{if(!confirm('ลบภาพนี้จากเว็บและย้ายไฟล์ใน Drive ไปถังขยะ? ประวัติและเวลาจะยังคงอยู่'))return;remove.disabled=true;try{await VC_API.call('deleteLoanPhoto',{id:loan.id,phase});loanPhotoCache.delete(key);document.querySelector('#photoViewer').close();await loadEquipment();}catch(e){status.textContent=e.message;container.append(status);remove.disabled=false;}});container.append(remove);}}catch(error){status.textContent='โหลดภาพไม่สำเร็จ: '+error.message;const retry=document.createElement('button');retry.type='button';retry.className='retryphoto';retry.textContent='โหลดภาพใหม่';retry.addEventListener('click',()=>loadLoanPhoto(container,loan,phase));container.append(retry);}}
document.querySelector('#closeViewer').addEventListener('click',()=>document.querySelector('#photoViewer').close());
document.querySelector('#photoViewer').addEventListener('close',()=>document.querySelector('#viewerImage').removeAttribute('src'));
